// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.evaluation.NativeLmdbQuerySource;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Element access on adjacency runs larger than the full-materialization cap (8192 edges) must agree exactly with the
 * bulk-copy ground truth, in every access order. Runs this size are served scalar (or, after the windowed-read
 * optimization, from a decode window); the window boundary arithmetic and refills are exactly what this test guards.
 * The fixture builds one 9000-edge run in the default graph and one 9000-edge run in a named graph so both the neighbor
 * and the context columns cross the cap.
 */
@org.junit.jupiter.api.Timeout(180)
class LmdbDirectAdjacencyWindowedReadTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final IRI HUB = F.createIRI("http://example.org/hub");
	private static final IRI HUB_CTX = F.createIRI("http://example.org/hubCtx");
	private static final IRI P1 = F.createIRI("http://example.org/p1");
	private static final IRI G2 = F.createIRI("http://example.org/g2");
	private static final int EDGES = 9_000;

	@TempDir
	File dataDir;

	private Repository repo;
	private LmdbSailStore backing;

	@AfterEach
	void tearDown() {
		if (repo != null) {
			repo.shutDown();
		}
	}

	private NativeLmdbQuerySource openStoreWithHubRuns() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore sail = new LmdbStore(dataDir, config);
		repo = new SailRepository(sail);
		repo.init();
		try (RepositoryConnection conn = repo.getConnection()) {
			// One explicit transaction: per-add autocommit would create 18K commits and wedge the adjacency applier.
			conn.begin();
			for (int i = 0; i < EDGES; i++) {
				conn.add(HUB, P1, F.createIRI("http://example.org/o/" + i));
				conn.add(HUB_CTX, P1, F.createIRI("http://example.org/oc/" + i), G2);
			}
			conn.commit();
		}
		backing = sail.getBackingStore();
		assertThat(backing.directAdjacencyStore().buildNowForTest()).isTrue();
		return (NativeLmdbQuerySource) backing.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT);
	}

	@Test
	void scalarReadsOverAnOversizedRunMatchBulkCopyInEveryAccessOrder() throws Exception {
		NativeLmdbQuerySource dataset = openStoreWithHubRuns();
		try {
			scalarReadsMatchBulkCopy(dataset);
		} finally {
			((org.eclipse.rdf4j.sail.base.SailDataset) dataset).close();
		}
	}

	private void scalarReadsMatchBulkCopy(NativeLmdbQuerySource dataset) throws Exception {
		long hub = dataset.idOf(HUB);
		long p1 = dataset.idOf(P1);
		assertThat(hub).isPositive();
		assertThat(p1).isPositive();
		try (NativeLmdbQuerySource.NativeProbe probe = dataset.newProbe();
				NativeLmdbQuerySource.NativeAdjacency adjacency = probe.adjacency(p1, true)) {
			long run = adjacency.find(hub);
			assertThat(run).isPositive();
			int size = (int) adjacency.size(run);
			assertThat(size).isEqualTo(EDGES);

			long[] expected = new long[size];
			int copied = 0;
			while (copied < size) {
				copied += adjacency.copyNeighbors(run, copied, Math.min(1024, size - copied), expected, copied);
			}
			assertThat(copied).isEqualTo(size);

			// Forward sequential order (the kernel probe loops).
			for (int i = 0; i < size; i++) {
				assertThat(adjacency.neighborAt(run, i)).as("forward offset %d", i).isEqualTo(expected[i]);
			}
			// Backward order: every step is a window miss for a forward-filled window.
			for (int i = size - 1; i >= 0; i--) {
				assertThat(adjacency.neighborAt(run, i)).as("backward offset %d", i).isEqualTo(expected[i]);
			}
			// Strided jumps across window boundaries, including exact boundary offsets.
			for (int i = 0; i < size; i += 4093) {
				assertThat(adjacency.neighborAt(run, i)).as("stride offset %d", i).isEqualTo(expected[i]);
			}
			for (int boundary : new int[] { 4095, 4096, 4097, 8191, 8192, 8193, size - 1 }) {
				assertThat(adjacency.neighborAt(run, boundary)).as("boundary offset %d", boundary)
						.isEqualTo(expected[boundary]);
			}
		}
	}

	@Test
	void contextReadsOverAnOversizedNamedGraphRunMatchBulkCopy() throws Exception {
		NativeLmdbQuerySource dataset = openStoreWithHubRuns();
		try {
			contextReadsMatchBulkCopy(dataset);
		} finally {
			((org.eclipse.rdf4j.sail.base.SailDataset) dataset).close();
		}
	}

	private void contextReadsMatchBulkCopy(NativeLmdbQuerySource dataset) throws Exception {
		long hubCtx = dataset.idOf(HUB_CTX);
		long p1 = dataset.idOf(P1);
		long g2 = dataset.idOf(G2);
		assertThat(hubCtx).isPositive();
		assertThat(g2).isPositive();
		try (NativeLmdbQuerySource.NativeProbe probe = dataset.newProbe();
				NativeLmdbQuerySource.NativeAdjacency adjacency = probe.adjacency(p1, true)) {
			long run = adjacency.find(hubCtx);
			assertThat(run).isPositive();
			int size = (int) adjacency.size(run);
			assertThat(size).isEqualTo(EDGES);

			long[] expectedNeighbors = new long[size];
			long[] expectedContexts = new long[size];
			int copied = 0;
			while (copied < size) {
				int batch = adjacency.copyNeighbors(run, copied, Math.min(1024, size - copied), expectedNeighbors,
						copied);
				assertThat(adjacency.copyContexts(run, copied, batch, expectedContexts, copied)).isEqualTo(batch);
				copied += batch;
			}

			// Interleaved neighbor+context reads, forward then strided, keep both columns consistent.
			for (int i = 0; i < size; i++) {
				assertThat(adjacency.neighborAt(run, i)).isEqualTo(expectedNeighbors[i]);
				assertThat(adjacency.contextAt(run, i)).isEqualTo(expectedContexts[i]);
				assertThat(adjacency.contextAt(run, i)).isEqualTo(g2);
			}
			for (int i = size - 1; i >= 0; i -= 2731) {
				assertThat(adjacency.contextAt(run, i)).as("context stride offset %d", i)
						.isEqualTo(expectedContexts[i]);
			}
		}
	}
}
